def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'
    last_me, last_opp = history[-1]
    me = []
    op = []
    opp_c = 0
    for a, b in history:
        me.append(a)
        op.append(b)
        if b == 'C':
            opp_c += 1
    opp_coop_rate = opp_c / float(n)

    opp_D_streak = 0
    for i in range(n - 1, -1, -1):
        if op[i] == 'D':
            opp_D_streak += 1
        else:
            break

    opp_C_streak = 0
    for i in range(n - 1, -1, -1):
        if op[i] == 'C':
            opp_C_streak += 1
        else:
            break

    recent_d5 = sum(1 for x in op[-5:] if x == 'D')
    recent_d10 = sum(1 for x in op[-10:] if x == 'D')

    after_D_C = 0
    after_D_D = 0
    after_C_C = 0
    after_C_D = 0
    for i in range(n - 1):
        if me[i] == 'D':
            if op[i + 1] == 'C':
                after_D_C += 1
            else:
                after_D_D += 1
        else:
            if op[i + 1] == 'C':
                after_C_C += 1
            else:
                after_C_D += 1

    d_total = after_D_C + after_D_D
    c_total = after_C_C + after_C_D
    if d_total > 0:
        pd_after_D = after_D_D / float(d_total)
    else:
        pd_after_D = 0.5
    if c_total > 0:
        pd_after_C = after_C_D / float(c_total)
    else:
        pd_after_C = 0.5
    retaliatory = pd_after_D - pd_after_C

    if d_total >= 3 and c_total >= 3 and abs(retaliatory) < 0.18 and opp_coop_rate > 0.25:
        nonreactive = True
    else:
        nonreactive = False

    persistent_D = False
    if n >= 2 and opp_c == 0:
        persistent_D = True
    if n >= 15 and opp_coop_rate < 0.08:
        persistent_D = True
    if opp_D_streak >= 7 and opp_coop_rate < 0.45:
        persistent_D = True
    if recent_d10 == 10 and n >= 10 and opp_coop_rate < 0.5:
        persistent_D = True

    conf = 0.0
    if opp_c > 0 and not persistent_D:
        if d_total >= 3:
            fratio = after_D_C / float(d_total)
            if fratio >= 0.8 and d_total >= 4:
                conf = 0.9
            elif fratio >= 0.7:
                conf = 0.75
            elif fratio >= 0.6:
                conf = 0.6
            elif fratio >= 0.45:
                conf = 0.35
            elif fratio >= 0.3:
                conf = 0.15
            if retaliatory > 0.35:
                conf *= 0.35
            if retaliatory > 0.55:
                conf *= 0.1
        elif d_total > 0:
            if after_D_C >= after_D_D + 1:
                conf = 0.25
            elif after_D_C > after_D_D:
                conf = 0.15
        else:
            if n >= 20 and opp_coop_rate > 0.9:
                conf = 0.15
            if opp_C_streak >= 10 and opp_coop_rate > 0.8:
                if conf < 0.12:
                    conf = 0.12

        if nonreactive:
            if opp_coop_rate > 0.4:
                if conf < 0.7:
                    conf = 0.7
            else:
                if conf < 0.45:
                    conf = 0.45

        if opp_C_streak >= 8 and opp_coop_rate > 0.78 and retaliatory < 0.15:
            if conf < 0.45:
                conf = 0.45

        if last_me == 'D' and last_opp == 'C' and opp_C_streak >= 4 and retaliatory < 0.15:
            if conf < 0.5:
                conf = 0.5

        if n < 12:
            if conf > 0.1:
                conf = 0.1
        elif n < 20:
            if d_total >= 3 and after_D_C >= 3 * after_D_D:
                if conf > 0.55:
                    conf = 0.55
            elif d_total >= 3 and after_D_C >= 2 * after_D_D:
                if conf > 0.35:
                    conf = 0.35
            else:
                if conf > 0.2:
                    conf = 0.2
        elif n < 30:
            if d_total >= 3 and after_D_C >= 2 * after_D_D:
                if conf > 0.7:
                    conf = 0.7
            else:
                if conf > 0.4:
                    conf = 0.4

        if recent_d10 >= 6 and not nonreactive:
            conf *= 0.5

        if n >= 97:
            conf += 0.45
            if conf > 1.0:
                conf = 1.0
        elif n >= 95 and opp_coop_rate > 0.55:
            conf += 0.15
            if conf > 1.0:
                conf = 1.0

        if 100 - n <= 2:
            conf = 1.0

    if last_opp == 'D':
        if persistent_D or opp_c == 0:
            if rng.random() < 0.96:
                return 'D'
            return 'C'

        if conf >= 0.55 and retaliatory <= 0.2:
            if rng.random() < 0.9:
                return 'D'
            return 'C'

        if last_me == 'C' and n >= 2 and history[-2][0] == 'D' and history[-2][1] == 'C':
            if rng.random() < 0.85:
                return 'C'
            return 'D'

        if last_me == 'D':
            if opp_D_streak >= 6:
                if rng.random() < 0.6:
                    return 'D'
            if conf >= 0.45:
                if rng.random() < 0.55:
                    return 'D'
            if rng.random() < 0.85:
                return 'C'
            return 'D'

        if opp_D_streak >= 6:
            if rng.random() < 0.8:
                return 'D'
            return 'C'

        if opp_D_streak <= 1:
            if opp_coop_rate > 0.7:
                if rng.random() < 0.62:
                    return 'D'
                return 'C'
            if rng.random() < 0.85:
                return 'D'
            return 'C'

        if opp_D_streak <= 4 and opp_coop_rate > 0.6:
            if rng.random() < 0.75:
                return 'C'
            return 'D'

        if rng.random() < 0.8:
            return 'D'
        return 'C'

    p = conf

    if persistent_D:
        if rng.random() < 0.75:
            return 'D'
        return 'C'

    if last_me == 'D':
        if p < 0.8:
            p = 0.18
        if nonreactive and opp_C_streak >= 5:
            if p < 0.6:
                p = 0.6

    if opp_D_streak >= 2:
        p *= 0.5

    if recent_d10 >= 6 and not nonreactive:
        p *= 0.35

    if last_me == 'D' and n >= 2 and history[-2][1] == 'D' and not nonreactive:
        if p > 0.15:
            p = 0.15

    if n >= 98:
        p += 0.35
        if p > 1.0:
            p = 1.0
    elif n >= 96 and opp_coop_rate > 0.5:
        p += 0.1
        if p > 1.0:
            p = 1.0

    if p < 0.12 and opp_C_streak >= 6 and recent_d5 == 0 and n >= 18:
        p = 0.22

    if p < 0.08 and opp_C_streak >= 10 and opp_coop_rate > 0.75:
        p = 0.18

    if rng.random() < p:
        return 'D'
    return 'C'
